package autoclaw

// This file implements the parsing, ownership determination, masking, and write-back merging of AutoClaw credentials.
//
// Credential format (aligned with Agent2API's auths/autoclaw-*.json):
//
//	{
//	  "vendor": "autoclawcn",
//	  "accessToken": "eyJ…",
//	  "refreshToken": "eyJ…",
//	  "expiresAt": 1780000000,
//	  "userId": "123",
//	  "userName": "…",
//	  "region": "cn"
//	}
//
// Login credentials are generated by the SMS / OAuth flow in login.go; refresh_token supports automatic refresh.

import (
	"encoding/json"
	"errors"
	"fmt"
	"strings"
	"sync"

	"free-model-hub/internal/core"
)

// Regional instance identifier. Also used as the credential filename prefix (autoclawcn-<uid>.json, etc.).
const (
	VendorIDCN     = "autoclawcn"
	VendorIDGlobal = "autoclawglobal"
	// protocolName is the family alias (used for filename infix matching, such as my-autoclaw.json).
	protocolName = "autoclaw"
)

// Display name.
const (
	VendorNameCN     = "AutoClaw CN"
	VendorNameGlobal = "AutoClaw Global"
)

// VendorIDFor returns the instance identifier corresponding to the region.
func VendorIDFor(region Region) string {
	if region.IsGlobal() {
		return VendorIDGlobal
	}
	return VendorIDCN
}

// VendorNameFor returns the display name corresponding to the region.
func VendorNameFor(region Region) string {
	if region.IsGlobal() {
		return VendorNameGlobal
	}
	return VendorNameCN
}

// Region is the deployment region of AutoClaw.
type Region string

const (
	RegionCN     Region = "cn"
	RegionGlobal Region = "global"
)

// IsGlobal reports whether it is a global deployment.
func (r Region) IsGlobal() bool { return r == RegionGlobal }

// NormalizeRegion normalizes any region string (unknown values fall back to cn).
func NormalizeRegion(raw string) Region {
	switch strings.ToLower(strings.TrimSpace(raw)) {
	case string(RegionGlobal), "intl", "international":
		return RegionGlobal
	default:
		return RegionCN
	}
}

// RegionForCredential infers the region from the credential JSON, returning an empty string if it cannot be inferred.
func RegionForCredential(raw map[string]any) string {
	if raw == nil {
		return ""
	}
	for _, key := range []string{"region", "realm"} {
		if value, okValue := raw[key].(string); okValue {
			trimmed := strings.ToLower(strings.TrimSpace(value))
			if trimmed == string(RegionCN) || trimmed == string(RegionGlobal) {
				return trimmed
			}
		}
	}
	return ""
}

// ErrMissingToken indicates that there is no available access token in the credential.
var ErrMissingToken = errors.New("credential has no accessToken")

// Credential is the normalized AutoClaw credential.
//
// Concurrency conventions are consistent with core.Credential: outbound reads use getter methods with locked snapshots,
// and the refresh goroutine concurrently rewrites token fields.
type Credential struct {
	mu sync.Mutex

	AccessToken  string
	RefreshToken string
	// ExpiresAt is the access token expiration time (Unix seconds); 0 means unknown.
	// Upstream login response lacks expires_in, so Agent2API conservatively caches it for 28 days.
	ExpiresAt int64
	UID       string
	UserName  string
	Phone     string
	// DeviceID is the login device identifier (refresh requests need to send it back as-is).
	DeviceID string
	Region   Region
	// SandboxID / SandboxEndpoint are cloud sandbox identifiers and endpoints (optional; not needed when
	// chat goes through the region proxy path; retained for subsequent integration with sandbox relay channels).
	SandboxID       string
	SandboxEndpoint string
}

// ParseCredential parses the AutoClaw credential JSON.
func ParseCredential(raw []byte) (*Credential, error) {
	if len(raw) == 0 {
		return nil, fmt.Errorf("credential is empty")
	}
	var payload map[string]any
	if errUnmarshal := json.Unmarshal(raw, &payload); errUnmarshal != nil {
		return nil, fmt.Errorf("credential is not valid JSON: %w", errUnmarshal)
	}
	cred := &Credential{}
	getStr := func(keys ...string) string {
		for _, key := range keys {
			if value, okValue := payload[key].(string); okValue && strings.TrimSpace(value) != "" {
				return strings.TrimSpace(value)
			}
		}
		return ""
	}
	cred.AccessToken = getStr("accessToken", "access_token", "token")
	cred.RefreshToken = getStr("refreshToken", "refresh_token")
	cred.UserName = getStr("userName", "user_name", "name", "label")
	cred.Phone = getStr("phone")
	cred.DeviceID = getStr("deviceId", "device_id")
	cred.SandboxID = getStr("sandboxId", "sandbox_id")
	cred.SandboxEndpoint = getStr("sandboxEndpoint", "sandbox_endpoint")
	if uid, okUID := payload["userId"]; okUID {
		switch value := uid.(type) {
		case string:
			cred.UID = strings.TrimSpace(value)
		case float64:
			cred.UID = strings.TrimSuffix(fmt.Sprintf("%.0f", value), ".0")
		}
	}
	if cred.UID == "" {
		cred.UID = getStr("uid", "user_id")
	}
	if cred.DeviceID == "" {
		// Consistent with Agent2API: deviceId is allowed to be empty, and uid is used as a fallback when empty
		// (refresh requests echo it back as-is per account, as upstream only requires stability).
		cred.DeviceID = strings.TrimSpace(cred.UID)
	}
	if region := RegionForCredential(payload); region != "" {
		cred.Region = NormalizeRegion(region)
	} else if vendor, okVendor := payload[core.VendorKey].(string); okVendor {
		// Infer it if the vendor field contains a region (autoclawcn / autoclawglobal).
		if strings.Contains(strings.ToLower(vendor), "global") {
			cred.Region = RegionGlobal
		} else if strings.Contains(strings.ToLower(vendor), protocolName) {
			cred.Region = RegionCN
		}
	}
	if seconds := core.GetUnixSeconds(payload, "expiresAt", "expires_at"); seconds > 0 {
		cred.ExpiresAt = seconds
	}
	if strings.TrimSpace(cred.AccessToken) == "" {
		return nil, ErrMissingToken
	}
	return cred, nil
}

// LooksLikeCredential determines whether a JSON belongs to AutoClaw (in any region).
//
// **Ownership determination must be strictly conservative** (following the same discipline across providers): the host feeds all
// non-built-in formats of credentials into each plugin sequentially, and mis-swallowing another plugin's format will cause
// the host to overwrite the other account with this plugin's structure (silently). Failing to recognize it just causes a load failure, which the user notices immediately, with a much lower cost.
//
// Only accept evidence specific to AutoClaw:
//  1. Filename contains an autoclaw segment (autoclawcn / autoclawglobal / my-autoclaw, etc.);
//  2. Credential explicitly declares vendor: autoclaw*;
//  3. Credential possesses the characteristic combination of AutoClaw (sandboxEndpoint or X-side device field name).
//
// Deliberately do not accept generic field names like accessToken / refreshToken as criteria: workbuddy,
// trae, etc. also use them, and using generic names as criteria will inevitably lead to cross-provider mis-swallowing.
func LooksLikeCredential(raw map[string]any, fileName, provider string) bool {
	if core.FileNameMatchesConvention(fileName, VendorIDCN, VendorIDGlobal, protocolName) {
		return true
	}
	if raw == nil {
		return false
	}
	if vendor, okVendor := raw[core.VendorKey].(string); okVendor {
		trimmed := strings.ToLower(strings.TrimSpace(vendor))
		if strings.HasPrefix(trimmed, protocolName) {
			return true
		}
	}
	// Characteristic combination: sandbox endpoint field exclusive to Agent2API credentials.
	// deviceId / device_id appearing alone is too broad (used by qoder, etc.) and is not used as a criterion.
	for _, key := range []string{"sandboxEndpoint", "sandbox_endpoint"} {
		if _, okKey := raw[key]; okKey {
			return true
		}
	}
	_ = provider
	return false
}

// ---- Locked Getters (for concurrent outbound use) ----

// AccessTokenValue returns the access token of the locked snapshot.
func (c *Credential) AccessTokenValue() string {
	if c == nil {
		return ""
	}
	c.mu.Lock()
	defer c.mu.Unlock()
	return c.AccessToken
}

// RefreshTokenValue returns the refresh token of the locked snapshot.
func (c *Credential) RefreshTokenValue() string {
	if c == nil {
		return ""
	}
	c.mu.Lock()
	defer c.mu.Unlock()
	return c.RefreshToken
}

// ExpiresAtValue returns the expiration time (Unix seconds) of the locked snapshot.
func (c *Credential) ExpiresAtValue() int64 {
	if c == nil {
		return 0
	}
	c.mu.Lock()
	defer c.mu.Unlock()
	return c.ExpiresAt
}

// UIDValue returns the user ID of the locked snapshot.
func (c *Credential) UIDValue() string {
	if c == nil {
		return ""
	}
	c.mu.Lock()
	defer c.mu.Unlock()
	return c.UID
}

// DeviceIDValue returns the device ID of the locked snapshot.
func (c *Credential) DeviceIDValue() string {
	if c == nil {
		return ""
	}
	c.mu.Lock()
	defer c.mu.Unlock()
	return c.DeviceID
}

// UserNameValue returns the display name of the locked snapshot.
func (c *Credential) UserNameValue() string {
	if c == nil {
		return ""
	}
	c.mu.Lock()
	defer c.mu.Unlock()
	return c.UserName
}

// UnchangedSince reports whether both tokens remain unchanged before and after the refresh.
func (c *Credential) UnchangedSince(accessBefore, refreshBefore string) bool {
	if c == nil {
		return true
	}
	c.mu.Lock()
	defer c.mu.Unlock()
	return c.AccessToken == accessBefore && c.RefreshToken == refreshBefore
}

// Snapshot returns the token pair of the locked snapshot.
func (c *Credential) Snapshot() (access, refresh string) {
	if c == nil {
		return "", ""
	}
	c.mu.Lock()
	defer c.mu.Unlock()
	return c.AccessToken, c.RefreshToken
}

// ApplyTokens writes the refresh result (an empty refresh token indicates that the upstream did not rotate, keeping the old value).
func (c *Credential) ApplyTokens(access, refresh string, expiresAt int64) {
	if c == nil {
		return
	}
	c.mu.Lock()
	defer c.mu.Unlock()
	if strings.TrimSpace(access) != "" {
		c.AccessToken = strings.TrimSpace(access)
	}
	if strings.TrimSpace(refresh) != "" {
		c.RefreshToken = strings.TrimSpace(refresh)
	}
	if expiresAt > 0 {
		c.ExpiresAt = expiresAt
	}
}

// Realm returns the region to which the credential belongs.
func (c *Credential) Realm() Region {
	if c == nil {
		return RegionCN
	}
	c.mu.Lock()
	defer c.mu.Unlock()
	return c.Region
}

// StorageJSON serializes the credential into persistence JSON (the vendor field redundantly declares ownership).
func (c *Credential) StorageJSON() ([]byte, error) {
	if c == nil {
		return nil, fmt.Errorf("credential is nil")
	}
	c.mu.Lock()
	defer c.mu.Unlock()
	payload := map[string]any{
		core.VendorKey: VendorIDFor(c.Region),
		"accessToken":  c.AccessToken,
		"refreshToken": c.RefreshToken,
		"expiresAt":    c.ExpiresAt,
		"region":       string(c.Region),
	}
	if c.UID != "" {
		payload["userId"] = c.UID
	}
	if c.UserName != "" {
		payload["userName"] = c.UserName
	}
	if c.Phone != "" {
		payload["phone"] = c.Phone
	}
	if c.DeviceID != "" {
		payload["deviceId"] = c.DeviceID
	}
	if c.SandboxID != "" {
		payload["sandboxId"] = c.SandboxID
	}
	if c.SandboxEndpoint != "" {
		payload["sandboxEndpoint"] = c.SandboxEndpoint
	}
	return json.MarshalIndent(payload, "", "  ")
}

// ---------------------------------------------------------------------------
// Credential write-back merging
// ---------------------------------------------------------------------------

// Reuse the core.MergeCredentialJSON skeleton: only overwrite token-related fields,
// while manually maintained fields such as note / disabled are preserved as-is.

// MergeCredentialJSON merges the refreshed token back into the original credential JSON.
func MergeCredentialJSON(original []byte, cred *Credential) ([]byte, error) {
	return core.MergeCredentialJSON(original, cred.StorageJSON, func(target map[string]any) {
		target["accessToken"] = cred.AccessTokenValue()
		target["refreshToken"] = cred.RefreshTokenValue()
		target["expiresAt"] = cred.ExpiresAtValue()
	})
}
